#include <bits/stdc++.h>
using namespace std;
static const int MOD=998244353;
int main() {
	// your code goes here
	int t;
	scanf("%d",&t);
	while(t--)
	{
	    int n;
	    scanf("%d",&n);
	    vector<int>a(n+1);
	    vector<int>start(n+2,0),ord(n);
	    for(int i=1;i<=n;i++)
	    {
	        scanf("%d",&a[i]);
	        start[a[i]+1]++;
	    }
	    for(int v=1;v<=n+1;v++)start[v]+=start[v-1];
	    {
	        vector<int>pos(start.begin(),start.end());
	        for(int i=1;i<=n;i++) ord[pos[a[i]]++]=i;
	    }
	    vector<int>dL(n+2,0),dR(n+2,0),nL(n+2,0),nR(n+2,0);
	    dR[0]=1;
	    for(int s=1;s<=n;s++)
	    {
	        int lo=start[s],hi=start[s+1];
	        for(int l=0;l<=s;l++)
	        {
	            int r=s-l;
	            int vL=0,vR=0;
	            if(l>=1) vL=(dL[l-1]+dR[l-1])%MOD;
	            if(r>=1) vR=(dL[l]+dR[l])%MOD;
	            if(vL|vR)
	            {
	                bool okL=true,okR=true;
	                for(int q=lo;q<hi && (okL||okR);q++)
	                {
	                    int i=ord[q];
	                    if(i<=l)
	                    {
	                        bool g=(s==(n+i)/2);
	                        okR=okR && g;
	                        okL=okL && (g || (i==l && i==1));
	                    }
	                    else if (i>=n-r+1)
	                    {
	                        bool g=(s==n-i/2);
	                        okL=okL && g;
	                        okR=okR && (g || ( i==n-r+1 && i==n));
	                        
	                    }
	                    else
	                    {
	                        int j=(i+1)/2,u=(n-i+2)/2;
	                        okL=okL && (l==j);
	                        okR=okR && (r==u);
	                    }
	                }
	                nL[l]=okL?vL:0;
	                nR[l]=okR?vR:0;
	                
	            }
	            else{
	                nL[l]=nR[l]=0;
	            }
	            
	        }
	        swap(dL,nL);
	        swap(dR,nR);
	    }
	    long long ans=0;
	    for(int i=1;i<=n;i++) ans+=dL[i];
	    printf("%lld\n",ans%MOD);
	}
	return 0;
	

}
